import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const root = new Group();

  // Plane geometry – size will be controlled by parent positioning/scaling
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  material.color = new Color(0xffffff);

  // Async texture load (synchronous function body)
  if (config?.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // texture loading failure – keep material without map
      });
  }

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Handlers placeholder – no interactions defined for this node
  root.userData.handlers = {};

  // Cleanup: dispose resources and kill any GSAP timelines (none used here)
  root.userData.cleanup = () => {
    // Dispose material map if it was loaded
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines that might have been created in the future
    gsap.globalTimeline.clear();
  };

  return root;
}
